    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 20px;
}

main {
    width: 100%;
}

.container {
    background: white;
    border-radius: 12px;
    padding: 40px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.15);
    max-width: 500px;
    margin: 0 auto;
}

h1 {
    font-size: 28px;
    color: #1a1a1a;
    margin-bottom: 8px;
    font-weight: 600;
}

.subtitle {
    color: #666;
    font-size: 14px;
    margin-bottom: 32px;
    line-height: 1.5;
}

form {
    display: flex;
    flex-direction: column;
    gap: 24px;
}

.form-field {
    display: flex;
    flex-direction: column;
    gap: 6px;
}

label {
    font-size: 14px;
    font-weight: 500;
    color: #1a1a1a;
}

label span {
    color: #ef4444;
}

input[type="text"],
input[type="email"],
input[type="tel"] {
    padding: 10px 12px;
    font-size: 14px;
    border: 2px solid #e5e7eb;
    border-radius: 6px;
    font-family: inherit;
    transition: border-color 0.2s, box-shadow 0.2s;
}

input[type="text"]:focus,
input[type="email"]:focus,
input[type="tel"]:focus {
    outline: none;
    border-color: #667eea;
    box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.1);
}

input[type="text"]:hover,
input[type="email"]:hover,
input[type="tel"]:hover {
    border-color: #d1d5db;
}

input[aria-invalid="true"] {
    border-color: #ef4444;
}

input[aria-invalid="true"]:focus {
    border-color: #ef4444;
    box-shadow: 0 0 0 3px rgba(239, 68, 68, 0.1);
}

.help-text {
    font-size: 12px;
    color: #666;
    line-height: 1.4;
}

.error-message {
    font-size: 12px;
    color: #ef4444;
    line-height: 1.4;
    display: none;
}

.error-message.visible {
    display: block;
}

.submit-btn {
    padding: 12px 20px;
    font-size: 14px;
    font-weight: 600;
    color: white;
    background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
    border: none;
    border-radius: 6px;
    cursor: pointer;
    transition: transform 0.2s, box-shadow 0.2s;
    margin-top: 8px;
}

.submit-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 16px rgba(102, 126, 234, 0.3);
}

.submit-btn:active {
    transform: translateY(0);
}

.submit-btn:focus {
    outline: none;
    box-shadow: 0 0 0 3px rgba(102, 126, 234, 0.3);
}

.success-message {
    margin-top: 20px;
    padding: 16px;
    background: #d1fae5;
    border-left: 4px solid #10b981;
    border-radius: 6px;
    color: #047857;
    font-size: 14px;
}

.success-message.visible {
    display: block;
}

.success-message[aria-hidden="true"] {
    display: none;
}

/* Responsive design */
@media (max-width: 480px) {
    .container {
        padding: 24px;
    }

    h1 {
        font-size: 24px;
    }

    .subtitle {
        font-size: 13px;
        margin-bottom: 24px;
    }

    form {
        gap: 20px;
    }
}

/* High contrast mode support */
@media (prefers-contrast: more) {
    input[type="text"],
    input[type="email"],
    input[type="tel"] {
        border-width: 3px;
    }

    label span {
        font-weight: 700;
    }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
    * {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
    }

    input[type="text"]:focus,
    input[type="email"]:focus,
    input[type="tel"]:focus,
    .submit-btn:hover {
        transform: none;
    }
}
